<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE']);$db=Database::connection();$sid=(int)($_GET['souscription_id']??$_POST['souscription_id']??0);$s=$db->prepare("SELECT s.*,o.prime_totale,p.duree_mois,p.nom produit,co.raison_sociale compagnie FROM souscriptions s JOIN offres_devis o ON o.id=s.offre_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id WHERE s.id=? AND s.statut='acceptee'");$s->execute([$sid]);$r=$s->fetch()?:exit('Souscription acceptée introuvable.');$effect=$_POST['date_effet']??date('Y-m-d');$mode=$_POST['mode_paiement']??'virement';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!$effect)$errors[]='Date d’effet obligatoire.';if(!$errors){$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM contrats')->fetchColumn();$police='POL-'.date('Y').'-'.str_pad((string)$next,5,'0',STR_PAD_LEFT);$end=date('Y-m-d',strtotime($effect.' +'.(int)$r['duree_mois'].' months -1 day'));try{$db->prepare("INSERT INTO contrats(souscription_id,numero_police,date_effet,date_echeance,prime_annuelle,mode_paiement,statut) VALUES(?,?,?,?,?,?,'actif')")->execute([$sid,$police,$effect,$end,$r['prime_totale'],$mode]);$id=(int)$db->lastInsertId();audit('CREATION','contrat',$id);flash('success','Contrat créé avec succès.');redirect('contrats/index.php');}catch(PDOException){$errors[]='Un contrat existe déjà pour cette souscription.';}}}$title='Nouveau contrat';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><h1 class="h3">Créer le contrat</h1><a class="btn btn-outline-secondary" href="<?= APP_URL ?>/souscriptions/index.php">Retour</a></div><?php if($errors): ?><div class="alert alert-danger"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="card card-body"><?= csrf_field() ?><input type="hidden" name="souscription_id" value="<?= $sid ?>"><p><strong><?= e($r['compagnie'].' · '.$r['produit']) ?></strong><br>Prime : <?= number_format((float)$r['prime_totale'],0,',',' ') ?> FCFA</p><div class="row g-3"><div class="col-md-6"><label class="form-label">Date d’effet</label><input type="date" class="form-control" name="date_effet" value="<?= e($effect) ?>" required></div><div class="col-md-6"><label class="form-label">Mode de paiement</label><select class="form-select" name="mode_paiement"><?php foreach(['especes','cheque','virement','mobile_money','prelevement'] as $m): ?><option <?= $mode===$m?'selected':'' ?>><?= e($m) ?></option><?php endforeach ?></select></div></div><div class="text-end mt-4"><button class="btn btn-primary">Émettre le contrat</button></div></form></div><?php require __DIR__.'/../../includes/footer.php'; ?>
